fn dispatch_262209(payload: &[u8]) -> Option<usize> {
    let _ = payload;
    let m_0_8_u_0 = crate::engine::bits::extract_bits(payload, 0, 8, false, 0).map(|e| e.value);
    if m_0_8_u_0 == Some(1) { return Some(Idx::ACTISENSE_PRODUCT_INFO_MAIN as usize); }
    if m_0_8_u_0 == Some(2) { return Some(Idx::ACTISENSE_PRODUCT_INFO_MODEL_ID as usize); }
    if m_0_8_u_0 == Some(3) { return Some(Idx::ACTISENSE_PRODUCT_INFO_SOFTWARE_VERSION as usize); }
    if m_0_8_u_0 == Some(4) { return Some(Idx::ACTISENSE_PRODUCT_INFO_HARDWARE_VERSION as usize); }
    if m_0_8_u_0 == Some(5) { return Some(Idx::ACTISENSE_PRODUCT_INFO_SERIAL_NUMBER as usize); }
    if m_0_8_u_0 == Some(6) { return Some(Idx::ACTISENSE_PRODUCT_INFO as usize); }
    None
}
/// Pick the right PgnInfo variant for `pgn` given the frame payload.
pub fn dispatch(pgn: u32, payload: &[u8]) -> Option<usize> {
    match pgn {
        0 => Some(Idx::STANDARD_CAN_FRAME as usize),
        1728 => Some(Idx::QUICK_UNKNOWN6C0 as usize),
        1729 => Some(Idx::QUICK_CHAIN_COUNT as usize),
        1730 => Some(Idx::QUICK_UNKNOWN6C2 as usize),
        1731 => Some(Idx::QUICK_UNKNOWN6C3 as usize),
        262161 => Some(Idx::ACTISENSE_OPERATING_MODE as usize),
        262209 => dispatch_262209(payload),
        262384 => Some(Idx::ACTISENSE_STARTUP_STATUS as usize),
        262385 => Some(Idx::ACTISENSE_ERROR_REPORT as usize),
        262386 => Some(Idx::ACTISENSE_SYSTEM_STATUS as usize),
        262388 => Some(Idx::ACTISENSE_NEGATIVE_ACK as usize),
        262400 => Some(Idx::NMEA2000_GATEWAY_NETWORK_STATUS as usize),
        262656 => Some(Idx::CANBOAT_STARTUP as usize),
        262657 => Some(Idx::CANBOAT_NMEA0183_FILTER as usize),
        262658 => Some(Idx::CANBOAT_PGN_OVERRIDE as usize),
        _ => None,
    }
}
pub static FALLBACKS: &[(u32, u32)] = &[
    (0, Idx::STANDARD_CAN_FRAME as u32),
];
/// Largest Fallback:true PgnInfo whose pgn number is <= `pgn`.
/// Mirrors canboat's `searchForUnknownPgn`.
pub fn find_catchall(pgn: u32) -> Option<usize> {
    let i = FALLBACKS.partition_point(|&(p, _)| p <= pgn);
    if i == 0 { None } else { Some(FALLBACKS[i - 1].1 as usize) }
}
